package com.fixmer.mared.technology.workspace;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.network.chat.Component;import java.util.*;
/** Project roles do not grant server administration or execution privileges. */
public final class WorkspaceMembersScreen112 extends MaredScreen {
 private final WorkspaceScreen112 previous;private final WorkspaceClient112 client;private final String project;private Map<String,String> data;
 private EditBox target,newPath;private Button grant,revoke,roleButton,online,rename,delete;private String selected="VIEWER",saved="",pendingRole,pendingFileAction,pendingFilePath;private int left,w,scroll,maxScroll,onlineIndex;private long last;
 public WorkspaceMembersScreen112(WorkspaceScreen112 previous,WorkspaceClient112 client,String project,Map<String,String> data){super(WorkspaceScreen112.tr("members"));this.previous=previous;this.client=client;this.project=project;this.data=data;}
 private Component tr(String k,Object...args){return WorkspaceScreen112.tr(k,args);}private Button button(String k,int x,int y,int width,Runnable fn){return addRenderableWidget(Button.builder(tr(k),b->fn.run()).bounds(x,y,Math.max(1,width),20).build());}
 @Override protected void init(){if(target!=null)saved=target.getValue();client.attach();w=Math.max(1,Math.min(760,width-20));left=(width-w)/2;if(width<320||height<280){button("back",left,height-26,w,this::onClose);return;}target=addRenderableWidget(new EditBox(font,left,42,w,20,tr("target")));target.setMaxLength(36);target.setValue(saved);target.setHint(tr("target"));int bw=(w-12)/4;online=button("online",left,68,bw,this::online);roleButton=button("role.VIEWER",left+bw+4,68,bw,()->{List<String> roles=List.of("VIEWER","EDITOR","MANAGER");selected=roles.get((roles.indexOf(selected)+1)%roles.size());roleButton.setMessage(tr("role."+selected));});roleButton.setMessage(tr("role."+selected));grant=button("grant",left+2*(bw+4),68,bw,()->change(selected));revoke=button("revoke",left+3*(bw+4),68,w-3*(bw+4),()->change("NONE"));newPath=addRenderableWidget(new EditBox(font,left,96,Math.max(70,w-160),20,tr("path")));newPath.setMaxLength(120);newPath.setValue(previous.selectedFile().getOrDefault("path",""));rename=button("rename",left+w-156,96,76,()->fileAction("RENAME"));delete=button("delete",left+w-76,96,76,()->fileAction("DELETE"));button("back",left,height-26,w,this::onClose);refresh();tick();}
 private void online(){List<String> players=data.getOrDefault("players","").lines().filter(x->x.matches("[a-f0-9-]{36}\\|[A-Za-z0-9_]{1,16}")).toList();if(players.isEmpty())return;String[] p=players.get(Math.floorMod(onlineIndex++,players.size())).split("\\|",2);target.setValue(p[0]);online.setMessage(Component.literal(p[1]));}
 private void refresh(){if(client.busy())return;client.send(WorkspaceClient112.request("VIEW",project,"","","",0,0,"","",""),d->{if(d.containsKey("members"))data=d;else if("DENIED".equals(d.get("result")))data=Map.of();});}
 private void change(String role){if(client.busy())return;String id=target.getValue().trim().toLowerCase(Locale.ROOT);try{if(!UUID.fromString(id).toString().equals(id))throw new IllegalArgumentException();}catch(RuntimeException bad){client.result="INVALID";return;}saved=id;minecraft.setScreen(new ConfirmScreen(yes->{minecraft.setScreen(this);if(yes)pendingRole=role;},tr(role.equals("NONE")?"revoke":"grant"),tr("member_confirm",id,tr("role."+role))));}
 private void fileAction(String op){if(client.busy()||previous.selectedFile().isEmpty())return;String destination=newPath.getValue();minecraft.setScreen(new ConfirmScreen(yes->{minecraft.setScreen(this);if(yes){pendingFileAction=op;pendingFilePath=destination;}},tr(op.equals("DELETE")?"delete":"rename"),tr("file_confirm",tr(op.equals("DELETE")?"delete":"rename"),previous.selectedFile().get("path"))));}
 @Override public void tick(){client.tick();if(grant==null||width<320||height<280)return;boolean edit=client.connected()&&!client.busy()&&"OWNER".equals(data.get("role"));grant.active=revoke.active=roleButton.active=online.active=edit;target.setEditable(edit);boolean manage=client.connected()&&!client.busy()&&Set.of("OWNER","MANAGER").contains(data.getOrDefault("role","NONE"))&&!previous.selectedFile().isEmpty();rename.active=delete.active=manage;newPath.setEditable(manage);
  if(pendingRole!=null&&!client.busy()){String role=pendingRole;pendingRole=null;try{client.send(WorkspaceClient112.request("MEMBER",project,"","","",0,Long.parseLong(data.getOrDefault("projectRevision","0")),saved,role,""),d->{if(d.containsKey("members"))data=d;else refresh();});}catch(RuntimeException bad){client.result="INVALID";}}
  if(pendingFileAction!=null&&!client.busy()){String op=pendingFileAction,destination=pendingFilePath;pendingFileAction=null;var f=previous.selectedFile();if(!f.isEmpty())try{client.send(WorkspaceClient112.request(op,project,f.get("path"),f.get("file"),"",Long.parseLong(f.get("revision")),Long.parseLong(data.getOrDefault("projectRevision","0")),"","",op.equals("RENAME")?destination:""),d->{if(d.containsKey("members"))data=d;});}catch(RuntimeException bad){client.result="INVALID";}}
  long now=System.nanoTime();if(pendingRole==null&&pendingFileAction==null&&!client.busy()&&now-last>2_000_000_000L){last=now;refresh();}}
 @Override public void removed(){client.detach();}@Override public void onClose(){minecraft.setScreen(previous);}@Override public boolean isPauseScreen(){return false;}@Override public boolean mouseScrolled(double x,double y,double dx,double dy){scroll=Math.max(0,Math.min(maxScroll,scroll+(int)(-dy*20)));return true;}
 @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,0xFF13161E);g.drawCenteredString(font,title,width/2,8,0xFFFFFFFF);g.drawCenteredString(font,tr("status."+(client.connected()?client.result:"DISCONNECTED")),width/2,25,0xFFCCD0DC);if(width>=320&&height>=280){List<Component> text=new ArrayList<>();text.add(tr("permissions_help"));text.add(tr("role_help"));for(String row:data.getOrDefault("members","").split("\n")){String[] p=row.split("\\|",2);if(p.length==2)text.add(Component.literal(p[0]+" · ").append(tr("role."+p[1])));}text.add(tr("history"));for(String row:data.getOrDefault("history","").split("\n"))if(!row.isEmpty())text.add(Component.literal(row));List<net.minecraft.util.FormattedCharSequence> lines=new ArrayList<>();for(Component c:text)lines.addAll(font.split(c,w-4));int top=128,bottom=height-34,row=font.lineHeight+3;maxScroll=Math.max(0,lines.size()*row-(bottom-top));scroll=Math.min(scroll,maxScroll);g.enableScissor(left,top,left+w,bottom);try{int y=top-scroll;for(var line:lines){if(y+row>=top&&y<bottom)g.drawString(font,line,left,y,0xFFCCD0DC,false);y+=row;}}finally{g.disableScissor();}}else g.drawCenteredString(font,tr("resize"),width/2,60,0xFFDDDDDD);super.render(g,mx,my,dt);}
}
